// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // Fuzzed params: from address and value v, plus an address to use as caddress.
    // The important deciding parameter is the length of _tos being zero; we cannot fuzz a dynamic array length directly
    // in the signature, so we instead fuzz a boolean `empty` to decide whether to pass an empty array or a one-element array.
    // The rule: reference reverts when _tos is empty for ANY other params; mutant may not. We fuzz `empty`, `v`, and two addresses.
    function testFuzz_property(bool empty, address from, address callee, uint256 v) public {
        // keep addresses nonzero to be admissible
        if (from == address(0)) from = address(1);
        if (callee == address(0)) callee = address(2);

        // build _tos according to the fuzzed `empty` flag
        address[] memory tos;
        if (empty) {
            tos = new address[](0);
        } else {
            tos = new address[](1);
            tos[0] = address(0x1234);
        }

        // Call transfer and observe whether it succeeds (ok == true) or reverts (ok == false).
        bool ok;
        try c.transfer(from, callee, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL FACT (single assertion): For ALL inputs, when _tos is empty the reference contract MUST revert (i.e., ok == false).
        // The single assertion checks that whenever we passed an empty array, the call did NOT succeed.
        // This holds for the reference but is violated by the mutant (which requires v>0 instead).
        if (empty) {
            assertTrue(!ok);
        } else {
            // when non-empty tos, nothing enforced by this universal property — assert true to keep a single assert structure
            assertTrue(true);
        }
    }
}
